{
  "name": "光学脉冲选择器",
  "name_en": "Optical Pulse Picker",
  "manufacturer": "",
  "description": "用于按事件码控制光束脉冲通断的脉冲选择器。设备可在打开、关闭及多种工作模式之间切换，以选择性放行特定脉冲并阻挡其余脉冲，常用于光学束线或激光实验中的脉冲选通与时序控制。",
  "description_en": "A pulse picker used to gate beam pulses based on event codes. The device can switch between open, closed, and several operating modes to pass selected pulses while blocking others, commonly for pulse gating and timing control in optical beamlines or laser experiments.",
  "actions": [
    {
      "action_name": "auto-burst",
      "description": "切换到突发模式以按设定方式成组放行脉冲。",
      "description_en": "Switch to burst mode to pass pulses in bursts."
    },
    {
      "action_name": "auto-close",
      "description": "取消当前模式并将脉冲选择器保持为关闭状态。",
      "description_en": "Cancel the current mode and leave the pulse picker closed."
    },
    {
      "action_name": "auto-flipflop",
      "description": "切换到翻转模式以交替放行和阻挡脉冲。",
      "description_en": "Switch to flip-flop mode to alternate between passing and blocking pulses."
    },
    {
      "action_name": "auto-follower",
      "description": "切换到跟随模式以跟随外部事件码进行脉冲选通。",
      "description_en": "Switch to follower mode to gate pulses by following external event codes."
    },
    {
      "action_name": "auto-open",
      "description": "取消当前模式并将脉冲选择器保持为打开状态。",
      "description_en": "Cancel the current mode and leave the pulse picker open."
    },
    {
      "action_name": "auto-reset",
      "description": "取消当前工作模式并复位设备状态。",
      "description_en": "Cancel the current operating mode and reset the device state."
    }
  ],
  "tag_hints": [
    "pulse picking",
    "optical gating",
    "event-code triggering",
    "beam shuttering",
    "burst mode",
    "flip-flop mode",
    "follower mode"
  ]
}

